# owner: platform
import unittest

from hourglass.rounding import round_span_labels
from hourglass.models import Span


class RoundSpanLabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        self.assertEqual(
            round_span_labels([Span(543, 1036)], 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_halves_round_up(self):
        self.assertEqual(
            round_span_labels([Span(555, 1065)], 30), ["09:30-18:00 (8h 30m)"]
        )

    def test_end_of_day(self):
        self.assertEqual(
            round_span_labels([Span(1380, 1439)], 60), ["23:00-24:00 (1h 0m)"]
        )

    def test_empty(self):
        self.assertEqual(round_span_labels([], 15), [])

    def test_bad_steps(self):
        for step in (0, -15, 7, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_span_labels([Span(540, 1050)], step)

    def test_span_that_snaps_to_nothing(self):
        with self.assertRaises(ValueError):
            round_span_labels([Span(540, 544)], 15)
